def run_interactive_review(queue: ReviewQueue | None = None) -> None:
    """启动交互式审核会话。"""
    queue = queue or ReviewQueue()
    queue.load()

    print("\n" + "=" * 50)
    print("📋 NewsDesk 人工审核中心 (输入 help 查看命令)")
    print("=" * 50)

    while True:
        stats = queue.stats()
        print(f"\n当前队列状态: pending={stats.get('pending', 0)}  "
              f"approved={stats.get('approved', 0)}  "
              f"rejected={stats.get('rejected', 0)}  "
              f"published={stats.get('published', 0)}")

        try:
            cmd = input("\n> ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n👋 退出审核中心")
            break

        if cmd in ("quit", "exit", "q"):
            print("👋 退出")
            break

        elif cmd == "help":
            print("""
可用命令:
  list [status]        列出队列（可选状态过滤: pending/approved/rejected/published）
  show <id>            查看完整条目
  approve <id>         批准条目
  reject <id> [note]   拒绝条目（可加备注）
  modify <id> <plat>   编辑某平台文案（进入编辑器）
  stats                查看统计
  clean                清理已发布条目
  quit                 退出
            """.strip())

        elif cmd.startswith("list"):
            parts = cmd.split(maxsplit=1)
            filter_status = parts[1] if len(parts) > 1 else None
            items = queue.all()
            if filter_status:
                items = [it for it in items if it.status == filter_status]
            if not items:
                print("  队列为空")
                continue
            for it in items:
                print(f"  [{it.item_id[:8]}] {it.summary()}")

        elif cmd.startswith("show"):
            parts = cmd.split(maxsplit=1)
            if len(parts) < 2:
                print("  用法: show <item_id>")
                continue
            item = queue.find(parts[1])
            if not item:
                print(f"  找不到条目 {parts[1]}")
                continue
            print(f"\n{'='*50}")
            print(f"ID: {item.item_id}")
            print(f"标题: {item.event_title}")
            print(f"状态: {item.status}")
            print(f"标签: {', '.join(item.event_tags)}")
            print(f"链接: {item.event_url}")
            print(f"\n草稿:")
            for platform, text in item.drafts.items():
                print(f"\n  --- [{platform}] ---")
                print(f"  {text}")
            if item.history:
                print(f"\n历史 ({len(item.history)} 条):")
                for h in item.history[-5:]:
                    print(f"  {h['timestamp'][:16]} {h['action']} {h.get('note', '')}")

        elif cmd.startswith("approve"):
            parts = cmd.split(maxsplit=1)
            if len(parts) < 2:
                print("  用法: approve <item_id>")
                continue
            result = queue.approve(parts[1])
            if result:
                print(f"  ✅ 已批准 [{parts[1][:8]}]")
            else:
                print(f"  找不到条目 {parts[1]}")

        elif cmd.startswith("reject"):
            parts = cmd.split()
            if len(parts) < 2:
                print("  用法: reject <item_id> [note]")
                continue
            note = " ".join(parts[2:]) if len(parts) > 2 else ""
            result = queue.reject(parts[1], note=note)
            if result:
                print(f"  ❌ 已拒绝 [{parts[1][:8]}]")
            else:
                print(f"  找不到条目 {parts[1]}")

        elif cmd.startswith("modify"):
            parts = cmd.split()
            if len(parts) < 3:
                print("  用法: modify <item_id> <platform>")
                print("  platform: x / telegram / discord")
                continue
            item = queue.find(parts[1])
            if not item:
                print(f"  找不到条目 {parts[1]}")
                continue
            platform = parts[2]
            old_text = item.drafts.get(platform, "")
            print(f"\n  当前 [{platform}] 文案：\n  {'-'*40}")
            print(f"  {old_text}")
            print(f"  {'-'*40}")
            try:
                print("\n  输入新文案（Ctrl+D 或空行结束）：")
                lines: list[str] = []
                while True:
                    try:
                        line = input("  > ")
                    except EOFError:
                        break
                    if line == "" and lines:
                        break
                    lines.append(line)
                new_text = "\n".join(lines)
                if new_text.strip():
                    queue.modify_draft(parts[1], platform, new_text)
                    print(f"  ✏️  已修改 [{platform}]")
                else:
                    print("  未输入内容，取消")
            except KeyboardInterrupt:
                print("\n  取消编辑")

        elif cmd == "stats":
            for k, v in queue.stats().items():
                print(f"  {k}: {v}")

        elif cmd == "clean":
            deleted = queue.delete_published()
            print(f"  🗑️  已清理 {deleted} 条已发布记录")

        else:
            print(f"  未知命令 '{cmd}'，输入 help 查看帮助")

from __future__ import annotations

import re
import statistics
from pathlib import Path

from .config import SAMPLES_DIR
from .models import Style
from .rss import clean


def parse_samples(path: Path) -> list[str]:
    if not path.exists():
        return []
    raw = path.read_text(encoding="utf-8")
    parts = re.split(r"\n\s*\n", raw)
    return [clean(p) for p in parts if len(clean(p)) > 20]


def load_all_styles() -> dict[str, Style]:
    samples_path = Path(SAMPLES_DIR)
    return {
        "x": _analyze_from_file("x", samples_path / "x.txt"),
        "binance": _analyze_from_file("binance", samples_path / "biance.txt"),
        "okx": _analyze_from_file("okx", samples_path / "okx.txt"),
    }


def _analyze_from_file(name: str, path: Path) -> Style:
    posts = parse_samples(path)
    return analyze_style(name, posts)


def analyze_style(name: str, posts: list[str]) -> Style:
    if not posts:
        return Style.default(name)
    lengths = [len(p) for p in posts]
    emoji = sum(len(re.findall(r"[\U0001F300-\U0001FAFF]", p)) > 0 for p in posts) / len(posts)
    ticker = sum(("$" in p or "＃" in p or "#" in p) for p in posts) / len(posts)
    question = sum("？" in p or "?" in p for p in posts) / len(posts)
    first_lines = [p.split("。")[0][:40] for p in posts[:8]]
    return Style(name, int(statistics.median(lengths)), emoji, ticker, question, first_lines)


def adapt_to_style(base: str, style: Style, platform: str) -> str:
    text = base
    if style.ticker_rate > 0.4 and "$BTC" not in text and "$" not in text:
        text += "\n$BTC $ETH"
    if style.question_rate > 0.3 and "？" not in text:
        text += "\n你怎么看？"
    if platform == "x":
        text = "\n".join(text.split("\n")[:8])
    if platform == "okx" and len(text) > 480:
        text = text[:470] + "…"
    return text.strip()
